style.css:
*,
*::before,
*::after {
    color: #ffb6d9 !important;
}

/* Text inside inputs and textareas */
input,
textarea,
select,
button {
    color: #ffb6d9 !important;
}

/* Placeholder text */
::placeholder {
    color: #ffb6d9 !important;
    opacity: 1 !important;
}

/* Links */
a,
a:visited,
a:hover,
a:active {
    color: #ffb6d9 !important;
}
